class NeighborSum {
    vector<vector<int>> g;
    unordered_map<int, pair<int,int>> pos;
public:
    NeighborSum(vector<vector<int>>& grid) : g(grid) {
        for (int i = 0; i < (int)grid.size(); i++)
            for (int j = 0; j < (int)grid.size(); j++)
                pos[grid[i][j]] = {i, j};
    }
    int adjacentSum(int value) {
        auto [i, j] = pos[value];
        int n = g.size(), s = 0;
        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
        for (int k = 0; k < 4; k++) {
            int ni = i + dr[k], nj = j + dc[k];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n) s += g[ni][nj];
        }
        return s;
    }
    int diagonalSum(int value) {
        auto [i, j] = pos[value];
        int n = g.size(), s = 0;
        int dr[] = {1, 1, -1, -1}, dc[] = {1, -1, 1, -1};
        for (int k = 0; k < 4; k++) {
            int ni = i + dr[k], nj = j + dc[k];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n) s += g[ni][nj];
        }
        return s;
    }
};

