class NeighborSum {
    private int[][] g;
    private Map<Integer, int[]> pos = new HashMap<>();
    public NeighborSum(int[][] grid) {
        g = grid;
        for (int i = 0; i < grid.length; i++)
            for (int j = 0; j < grid.length; j++)
                pos.put(grid[i][j], new int[]{i, j});
    }
    private int sum(int value, int[] dr, int[] dc) {
        int[] p = pos.get(value);
        int n = g.length, s = 0;
        for (int k = 0; k < 4; k++) {
            int ni = p[0] + dr[k], nj = p[1] + dc[k];
            if (ni >= 0 && ni < n && nj >= 0 && nj < n) s += g[ni][nj];
        }
        return s;
    }
    public int adjacentSum(int value) {
        return sum(value, new int[]{1, -1, 0, 0}, new int[]{0, 0, 1, -1});
    }
    public int diagonalSum(int value) {
        return sum(value, new int[]{1, 1, -1, -1}, new int[]{1, -1, 1, -1});
    }
}

