class NeighborSum:
    def __init__(self, grid: list[list[int]]):
        n = len(grid)
        self.adj = [0] * (n * n)
        self.dia = [0] * (n * n)
        ADJ = ((1, 0), (-1, 0), (0, 1), (0, -1))
        DIA = ((1, 1), (1, -1), (-1, 1), (-1, -1))
        for i in range(n):
            for j in range(n):
                v = grid[i][j]
                for di, dj in ADJ:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        self.adj[grid[ni][nj]] += v
                for di, dj in DIA:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        self.dia[grid[ni][nj]] += v

    def adjacentSum(self, value: int) -> int:
        return self.adj[value]

    def diagonalSum(self, value: int) -> int:
        return self.dia[value]

